Algorithm Textos
  Define frase As String <- "  Hola, mundo  ";
  Define limpia As String <- trim(frase);
  Write "[", limpia, "] ", length(limpia);
  Write substring(limpia, 0, 3), " ", toUpper(limpia), " ", toLower("ÁRBOL");
  Write contains(limpia, "mundo"), " ", startsWith(limpia, "Ho"), " ", endsWith(limpia, "x");
  Write replace(limpia, "o", "0"), " ", charAt(limpia, 1), " ", charCode('A'), " ", charFromCode(97);
  Write padLeft("7", 3, '0'), " ", padRight("ab", 4, '.'), "|";
  Write join(split("a,b,c", ","), " - ");
EndAlgorithm
